		if (iconContainer) {
			const svgPath = iconContainer.querySelector("path");
			if (svgPath) {
				if (likedByMe) {
					// Filled heart when liked
					svgPath.setAttribute("d", filledHeartPath);
				} else {
					// Outline thumbs up when unliked
					svgPath.setAttribute("d", outlineHeartPath);
				}
			}
		}

		// Update like count
		if (countElement) {
			countElement.textContent = likeCount;
		}

		return result;
	} catch (error) {
		console.error("Error liking comment:", error);
		throw error;
	}
}




